```js
async function caricaFattura(req, res, next) {
  try {
    if (!mongoose.isValidObjectId(req.params.id)) return res.status(404).end();
    const fattura = await Fattura.findOne({ _id: req.params.id, utente: req.user.id });
    if (!fattura) return res.status(404).end();
    req.fattura = fattura;
    next();
  } catch (err) {
